import json,csv,hashlib,re
from pathlib import Path
R=Path(__file__).parent;P=R/'public'; sources={d['id']:d for d in json.loads((P/'sources.json').read_text())}
def write(name,rows):
 (P/(name+'.json')).write_text(json.dumps(rows,ensure_ascii=False,indent=2))
 if rows:
  keys=list(dict.fromkeys(k for x in rows for k in x))
  with (P/(name+'.csv')).open('w',newline='') as f:
   w=csv.DictWriter(f,fieldnames=keys);w.writeheader()
   for x in rows:w.writerow({k:json.dumps(v,ensure_ascii=False) if isinstance(v,(list,dict)) else v for k,v in x.items()})
rows=[]
